SET search_path TO steam_oltp;
CREATE TEMP TABLE stg_countries(country_code text,country_name text,region text);
\copy stg_countries FROM '../csv/countries.csv' CSV HEADER;
INSERT INTO countries(country_code,country_name,region) SELECT country_code,country_name,region FROM stg_countries ON CONFLICT (country_code) DO UPDATE SET country_name=EXCLUDED.country_name, region=EXCLUDED.region;
CREATE TEMP TABLE stg_users(username text,email text,country_code text,registration_date date);
\copy stg_users FROM '../csv/users.csv' CSV HEADER;
INSERT INTO users(username,email,country_id,registration_date) SELECT s.username,s.email,c.country_id,s.registration_date FROM stg_users s JOIN countries c ON c.country_code=s.country_code ON CONFLICT (username) DO UPDATE SET email=EXCLUDED.email, country_id=EXCLUDED.country_id, registration_date=EXCLUDED.registration_date;
CREATE TEMP TABLE stg_developers(developer_name text,country_code text);
\copy stg_developers FROM '../csv/developers.csv' CSV HEADER;
INSERT INTO developers(developer_name,country_id) SELECT s.developer_name,c.country_id FROM stg_developers s LEFT JOIN countries c ON c.country_code=s.country_code ON CONFLICT (developer_name) DO UPDATE SET country_id=EXCLUDED.country_id;
CREATE TEMP TABLE stg_publishers(publisher_name text,country_code text);
\copy stg_publishers FROM '../csv/publishers.csv' CSV HEADER;
INSERT INTO publishers(publisher_name,country_id) SELECT s.publisher_name,c.country_id FROM stg_publishers s LEFT JOIN countries c ON c.country_code=s.country_code ON CONFLICT (publisher_name) DO UPDATE SET country_id=EXCLUDED.country_id;
CREATE TEMP TABLE stg_genres(genre_name text);
\copy stg_genres FROM '../csv/genres.csv' CSV HEADER;
INSERT INTO genres(genre_name) SELECT genre_name FROM stg_genres ON CONFLICT (genre_name) DO NOTHING;
CREATE TEMP TABLE stg_games(game_slug text,title text,developer_name text,publisher_name text,release_date date,base_price numeric,age_rating text);
\copy stg_games FROM '../csv/games.csv' CSV HEADER;
INSERT INTO games(game_slug,title,developer_id,publisher_id,release_date,base_price,age_rating) SELECT s.game_slug,s.title,d.developer_id,p.publisher_id,s.release_date,s.base_price,s.age_rating FROM stg_games s JOIN developers d ON d.developer_name=s.developer_name JOIN publishers p ON p.publisher_name=s.publisher_name ON CONFLICT (game_slug) DO UPDATE SET title=EXCLUDED.title, developer_id=EXCLUDED.developer_id, publisher_id=EXCLUDED.publisher_id, release_date=EXCLUDED.release_date, base_price=EXCLUDED.base_price, age_rating=EXCLUDED.age_rating;
CREATE TEMP TABLE stg_game_genres(game_slug text,genre_name text);
\copy stg_game_genres FROM '../csv/game_genres.csv' CSV HEADER;
INSERT INTO game_genres(game_id,genre_id) SELECT g.game_id, ge.genre_id FROM stg_game_genres s JOIN games g ON g.game_slug=s.game_slug JOIN genres ge ON ge.genre_name=s.genre_name ON CONFLICT DO NOTHING;
CREATE TEMP TABLE stg_purchases(purchase_code text,username text,game_slug text,purchase_date date,paid_amount numeric,discount_percent int,payment_method text);
\copy stg_purchases FROM '../csv/purchases.csv' CSV HEADER;
INSERT INTO purchases(purchase_code,user_id,game_id,purchase_date,paid_amount,discount_percent,payment_method) SELECT s.purchase_code,u.user_id,g.game_id,s.purchase_date,s.paid_amount,s.discount_percent,s.payment_method FROM stg_purchases s JOIN users u ON u.username=s.username JOIN games g ON g.game_slug=s.game_slug ON CONFLICT (purchase_code) DO NOTHING;
CREATE TEMP TABLE stg_reviews(review_code text,username text,game_slug text,review_date date,rating int,comment text);
\copy stg_reviews FROM '../csv/reviews.csv' CSV HEADER;
INSERT INTO reviews(review_code,user_id,game_id,review_date,rating,comment) SELECT s.review_code,u.user_id,g.game_id,s.review_date,s.rating,s.comment FROM stg_reviews s JOIN users u ON u.username=s.username JOIN games g ON g.game_slug=s.game_slug ON CONFLICT (review_code) DO NOTHING;
CREATE TEMP TABLE stg_achievements(achievement_code text,game_slug text,achievement_name text,points int);
\copy stg_achievements FROM '../csv/achievements.csv' CSV HEADER;
INSERT INTO achievements(achievement_code,game_id,achievement_name,points) SELECT s.achievement_code,g.game_id,s.achievement_name,s.points FROM stg_achievements s JOIN games g ON g.game_slug=s.game_slug ON CONFLICT (achievement_code) DO UPDATE SET achievement_name=EXCLUDED.achievement_name, points=EXCLUDED.points;
CREATE TEMP TABLE stg_user_achievements(username text,achievement_code text,earned_date date);
\copy stg_user_achievements FROM '../csv/user_achievements.csv' CSV HEADER;
INSERT INTO user_achievements(user_id,achievement_id,earned_date) SELECT u.user_id,a.achievement_id,s.earned_date FROM stg_user_achievements s JOIN users u ON u.username=s.username JOIN achievements a ON a.achievement_code=s.achievement_code ON CONFLICT DO NOTHING;
CREATE TEMP TABLE stg_wishlist(username text,game_slug text,added_date date);
\copy stg_wishlist FROM '../csv/wishlist.csv' CSV HEADER;
INSERT INTO wishlist(user_id,game_id,added_date) SELECT u.user_id,g.game_id,s.added_date FROM stg_wishlist s JOIN users u ON u.username=s.username JOIN games g ON g.game_slug=s.game_slug ON CONFLICT DO NOTHING;
CREATE TEMP TABLE stg_price_history(game_slug text,valid_from date,valid_to date,price numeric,currency char(3));
\copy stg_price_history FROM '../csv/price_history.csv' CSV HEADER;
INSERT INTO price_history(game_id,valid_from,valid_to,price,currency) SELECT g.game_id,s.valid_from,s.valid_to,s.price,s.currency FROM stg_price_history s JOIN games g ON g.game_slug=s.game_slug ON CONFLICT (game_id, valid_from) DO UPDATE SET valid_to=EXCLUDED.valid_to, price=EXCLUDED.price, currency=EXCLUDED.currency;
